function placeDebugBase(){return{sequence:++placeDebugState.sequence,time:placeDebugTime(),result:null,visiblePlaces:state.visiblePlaces.length,visiblePlaceKey:state.visiblePlaceKey,currentVisiblePlaceKey:visiblePlaceKey(),nearestPlace:null,nearestDistance:null,secondPlace:null,secondDistance:null,pointerdown:false,pointermove:false,pointerup:false,kakaoClick:false,dragstart:false,dragend:false,idle:false,cacheInvalidate:false,cacheStale:placeDebugState.lastCacheStale,mapLevel:state.map?.getLevel?.()??null,visiblePlaceNames:state.visiblePlaces.map(place=>place.name||place.id).filter(Boolean)}}
