function placeDebugYes(value){return value?'YES':'NO'}
function placeDebugDistance(value){return Number.isFinite(value)?`${value.toFixed(1)} px`:'-'}
function renderPlaceDebugPanel(){if(!PLACE_DEBUG_ENABLED)return;const latest=placeDebugState.records.at(-1),active=placeDebugState.active,currentKey=visiblePlaceKey(),liveNames=state.visiblePlaces.map(place=>place.name||place.id).filter(Boolean);$('#placeDebugLatest').textContent=latest?.result||active?.result||'READY';$('#placeDebugCurrent').innerHTML=`live visiblePlaces: ${state.visiblePlaces.length} · level: ${state.map?.getLevel?.()??'-'}<br>cache stale: ${placeDebugYes(placeDebugState.lastCacheStale)} · key: ${state.visiblePlaceKey===currentKey?'MATCH':'MISMATCH'}<br>${esc(state.visiblePlaceKey||'-')}<br>${esc(currentKey||'-')}<br>visible: ${esc(liveNames.join(' | ')||'-')}`;$('#placeDebugRecords').innerHTML=placeDebugState.records.map(record=>`<li><b>${esc(record.time)} · ${esc(record.result)}</b><br>visiblePlaces: ${record.visiblePlaces} · level: ${record.mapLevel??'-'}<br>nearest: ${esc(record.nearestPlace||'-')} · ${placeDebugDistance(record.nearestDistance)}<br>second: ${esc(record.secondPlace||'-')} · ${placeDebugDistance(record.secondDistance)}<br><span class="debug-flags">pointer d/m/u: ${placeDebugYes(record.pointerdown)}/${placeDebugYes(record.pointermove)}/${placeDebugYes(record.pointerup)}<br>Kakao click: ${placeDebugYes(record.kakaoClick)} · drag s/e: ${placeDebugYes(record.dragstart)}/${placeDebugYes(record.dragend)} · idle: ${placeDebugYes(record.idle)}<br>cache invalidate/stale: ${placeDebugYes(record.cacheInvalidate)}/${placeDebugYes(record.cacheStale)}</span><br><span class="debug-keys">key: ${record.visiblePlaceKey===record.currentVisiblePlaceKey?'MATCH':'MISMATCH'}<br>${esc(record.visiblePlaceKey||'-')}<br>${esc(record.currentVisiblePlaceKey||'-')}</span><br><span class="debug-places">visible: ${esc(record.visiblePlaceNames.join(' | ')||'-')}</span></li>`).join('')}
function placeDebugCommit(result){if(!PLACE_DEBUG_ENABLED)return;const record=placeDebugActive();record.result=result;if(!placeDebugState.records.includes(record)){placeDebugState.records.push(record);placeDebugState.records=placeDebugState.records.slice(-10)}renderPlaceDebugPanel()}
function placeDebugGesture(name){if(!PLACE_DEBUG_ENABLED)return;if(name==='pointerdown'){clearTimeout(placeDebugState.noClickTimer);placeDebugState.active=placeDebugBase()}const record=placeDebugActive();if(name==='pointerdown')record.pointerdown=true;else if(name==='pointermove')record.pointermove=true;else if(name==='pointerup'){record.pointerup=true;const sequence=record.sequence;clearTimeout(placeDebugState.noClickTimer);placeDebugState.noClickTimer=setTimeout(()=>{if(placeDebugState.active?.sequence===sequence&&!record.kakaoClick&&!record.result)placeDebugCommit('NO_KAKAO_CLICK')},650)}else if(name==='click')record.kakaoClick=true;else if(name==='dragstart')record.dragstart=true;else if(name==='dragend')record.dragend=true;else if(name==='idle')record.idle=true;renderPlaceDebugPanel()}
