function placeDebugCache(details){if(!PLACE_DEBUG_ENABLED)return;placeDebugState.lastCacheStale=details?.stale===true;const record=placeDebugState.active;if(record&&!record.result)record.cacheStale=placeDebugState.lastCacheStale;renderPlaceDebugPanel()}
