function normalizeKakaoPlace(p){return{id:String(p.id||''),name:p.place_name||p.name||'',category:p.category_name||p.category||'',address:p.road_address_name||p.address_name||p.address||'',latitude:+(p.y??p.latitude),longitude:+(p.x??p.longitude),distance:p.distance==null||p.distance===''?null:+p.distance,phone:p.phone||''}}
function visiblePlaceKey(map=state.map){if(!map?.getBounds||!map?.getLevel)return'';const bounds=map.getBounds(),sw=bounds?.getSouthWest?.(),ne=bounds?.getNorthEast?.();if(!sw||!ne)return'';return[map.getLevel(),sw.getLng(),sw.getLat(),ne.getLng(),ne.getLat()].map((value,index)=>index?Number(value).toFixed(6):String(value)).join(':')}
function visibleBoundsLabel(map=state.map){const bounds=map?.getBounds?.(),sw=bounds?.getSouthWest?.(),ne=bounds?.getNorthEast?.();return sw&&ne?`${sw.getLng()},${sw.getLat()} → ${ne.getLng()},${ne.getLat()}`:''}
