async function refreshVisiblePlaces(){if(!state.map||!state.placesService)return[];const key=visiblePlaceKey();if(!key||state.map.getLevel()>VISIBLE_PLACE_MAX_LEVEL){state.visiblePlaces=[];state.visiblePlaceKey='';return[]}const cached=state.visiblePlaceCache.get(key);if(cached&&Date.now()-cached.createdAt<VISIBLE_PLACE_CACHE_TTL_MS){state.visiblePlaces=cached.places;state.visiblePlaceKey=key;logPlaceCache({bounds:visibleBoundsLabel(),zoom:state.map.getLevel(),generation:state.visiblePlaceGeneration,'category 요청 수':0,'성공 category 수':0,'실패 category 수':0,'총 검색 결과 수':cached.places.length,'중복 제거 후 visiblePlaces 수':cached.places.length,visiblePlaceKey:key,source:'CACHE'});placeDebugVisiblePlacesApplied();return cached.places}const generation=++state.visiblePlaceGeneration,OK=kakao.maps.services.Status.OK,ZERO=kakao.maps.services.Status.ZERO_RESULT;const searches=KAKAO_PLACE_CATEGORIES.map(category=>new Promise(resolve=>state.placesService.categorySearch(category,(places,status)=>resolve({ok:status===OK||status===ZERO,places:status===OK?places:[],status}),{useMapBounds:true,size:15})));const results=await Promise.all(searches),rawPlaces=results.flatMap(result=>result.places),unique=new Map();rawPlaces.map(normalizeKakaoPlace).filter(place=>place.id&&Number.isFinite(place.latitude)&&Number.isFinite(place.longitude)).forEach(place=>{if(!unique.has(place.id))unique.set(place.id,place)});const places=[...unique.values()],stale=generation!==state.visiblePlaceGeneration||key!==visiblePlaceKey(),failed=results.filter(result=>!result.ok).length;logPlaceCache({bounds:visibleBoundsLabel(),zoom:state.map.getLevel(),generation,'category 요청 수':KAKAO_PLACE_CATEGORIES.length,'성공 category 수':results.length-failed,'실패 category 수':failed,'총 검색 결과 수':rawPlaces.length,'중복 제거 후 visiblePlaces 수':places.length,visiblePlaceKey:key,'현재 visiblePlaceKey()':visiblePlaceKey(),stale,'cache 적용':!stale&&!failed});if(stale||failed)return state.visiblePlaces;cacheVisiblePlaces(key,places);state.visiblePlaces=places;state.visiblePlaceKey=key;placeDebugVisiblePlacesApplied();return places}
function visiblePlaceHitTest(point,places,projection){const candidates=!point||!projection?.pointFromCoords?[]:(places||[]).map(place=>{if(!Number.isFinite(+place.latitude)||!Number.isFinite(+place.longitude))return null;const projected=projection.pointFromCoords(new kakao.maps.LatLng(+place.latitude,+place.longitude)),dx=projected.x-point.x,dy=projected.y-point.y;return{place,projected:{x:projected.x,y:projected.y},distance:Math.hypot(dx,dy)}}).filter(Boolean).sort((a,b)=>a.distance-b.distance),nearby=candidates.filter(candidate=>candidate.distance<=PLACE_HIT_RADIUS_PX),ambiguous=!!(nearby[1]&&nearby[1].distance-nearby[0].distance<PLACE_AMBIGUITY_PX);return{candidates,nearest:candidates[0]||null,second:candidates[1]||null,ambiguous,selected:nearby.length&&!ambiguous?nearby[0].place:null}}
