function normalize(s){return String(s||'').replace(/\s+/g,'').toLowerCase()}
function isTransit(p){return /(지하철|철도|기차|역사|교통|수도권전철)/.test(p.category||'')}
function rankPlaces(list,q){const nq=normalize(q),station=/역$/.test(nq);return list.map((p,i)=>({p,i,score:(normalize(p.name)===nq?100000:0)+(station&&isTransit(p)?20000:0)+(normalize(p.name).startsWith(nq)?5000:0)+(normalize(p.name).includes(nq)?1000:0)})).sort((a,b)=>b.score-a.score||a.i-b.i||(a.p.distance??1e12)-(b.p.distance??1e12)).map(x=>x.p)}

async function loadKakao(){if(window.kakao?.maps)return;const cfg=await fetch('/api/config').then(r=>r.json());if(!cfg.kakaoJsKey)throw new Error(cfg.error||'Kakao JS key 없음');await new Promise((resolve,reject)=>{const s=document.createElement('script');s.src=`https://dapi.kakao.com/v2/maps/sdk.js?appkey=${encodeURIComponent(cfg.kakaoJsKey)}&autoload=false&libraries=services`;s.onload=()=>kakao.maps.load(resolve);s.onerror=reject;document.head.appendChild(s)})}
function pointSnapshot(point){return point&&Number.isFinite(+point.x)&&Number.isFinite(+point.y)?{x:+point.x,y:+point.y}:null}
function candidateName(candidate){return candidate?.place?.name||candidate?.place?.id||null}
