function handleMapClick(event){logPlaceGesture('click',event);const currentKey=visiblePlaceKey(),finish=(result,hit=null)=>{logPlaceTap(event,result,hit,currentKey);return null};if(state.screen==='navigation-place'){state.navigationSearch=false;history.back();return finish('WRONG_SCREEN')}if(state.screen==='place'){hideSheet();return finish('WRONG_SCREEN')}if(state.screen!=='map')return finish('WRONG_SCREEN');if(!event?.point)return finish('NO_EVENT_POINT');if(state.mapClickBlockedUntil===Infinity)return finish('BLOCKED_BY_DRAG');if(Date.now()<state.mapClickBlockedUntil)return finish('BLOCKED_BY_TIME');if(state.visiblePlaceKey!==currentKey)return finish('STALE_VIEWPORT');if(!state.visiblePlaces.length)return finish('NO_VISIBLE_PLACES');const hit=visiblePlaceHitTest(event.point,state.visiblePlaces,state.map?.getProjection?.());if(!hit.nearest||hit.nearest.distance>PLACE_HIT_RADIUS_PX)return finish('NO_NEARBY_PLACE',hit);if(hit.ambiguous)return finish('AMBIGUOUS',hit);openPlace(hit.selected);logPlaceTap(event,'SELECTED',hit,currentKey);return hit.selected}
function invalidateVisiblePlaces(reason='unknown'){console.groupCollapsed?.('[Place Cache Invalidate]');console.table?.({reason,timeStamp:Date.now(),screen:state.screen,generationBefore:state.visiblePlaceGeneration,visiblePlacesBefore:state.visiblePlaces.length,visiblePlaceKeyBefore:state.visiblePlaceKey,currentVisiblePlaceKey:visiblePlaceKey()});console.groupEnd?.();placeDebugInvalidate();state.visiblePlaceGeneration++;state.visiblePlaces=[];state.visiblePlaceKey=''}
function markSearchMapInteraction(){if(state.screen==='results')state.searchMapFitPending=false}
