function handleMapDragEnd(event){logPlaceGesture('dragend',event);state.mapClickBlockedUntil=Date.now()+350;if(state.screen==='results'&&!state.searchMapFitPending)ui.searchHere.classList.remove('hidden');endNavigationMapInteraction()}
