async function initMap(){syncViewportMetrics();await loadKakao();const fallback=new kakao.maps.LatLng(37.5665,126.9780);state.map=new kakao.maps.Map($('#map'),{center:fallback,level:5});state.map.setDraggable(true);state.map.setZoomable(true);state.placesService=new kakao.maps.services.Places(state.map);kakao.maps.event.addListener(state.map,'click',handleMapClick);kakao.maps.event.addListener(state.map,'dragstart',handleMapDragStart);kakao.maps.event.addListener(state.map,'dragend',handleMapDragEnd);kakao.maps.event.addListener(state.map,'zoom_start',handleMapZoomStart);kakao.maps.event.addListener(state.map,'zoom_changed',handleMapZoomChanged);kakao.maps.event.addListener(state.map,'idle',handleMapIdle);refreshVisiblePlaces();await locate(true).catch(()=>toast('현재 위치를 확인할 수 없습니다.'));renderScreen('map',false)}
function setGpsMarker(p,navigation=false,heading=0){if(!p||!state.map)return;const mode=navigation?'navigation':'map',ll=new kakao.maps.LatLng(p.latitude,p.longitude);if(!state.gpsMarker){state.gpsMarkerEl=document.createElement('div');state.gpsMarker=new kakao.maps.CustomOverlay({position:ll,content:state.gpsMarkerEl,zIndex:9,map:state.map})}if(state.gpsMarkerMode!==mode){state.gpsMarkerMode=mode;state.gpsMarkerEl.className=navigation?'gps-arrow':'gps-dot';state.gpsMarkerEl.textContent=navigation?'▲':'';state.gpsMarkerEl.style.cssText=navigation?'':'width:22px;height:22px;border-radius:50%;background:#1683ff;border:4px solid white;box-shadow:0 2px 8px #1683ff88'}if(navigation)state.gpsMarkerEl.style.transform=`rotate(${Number.isFinite(heading)?heading:0}deg)`;state.gpsMarker.setPosition(ll);state.gpsMarker.setMap(state.map)}
async function locate(center=false){const pos=await new Promise((res,rej)=>navigator.geolocation.getCurrentPosition(res,rej,{enableHighAccuracy:true,timeout:9000,maximumAge:5000}));const p={latitude:pos.coords.latitude,longitude:pos.coords.longitude,name:'현재 위치'};state.currentLocation=p;setGpsMarker(p,state.screen==='navigation',state.nav.heading);if(center){if(state.screen==='navigation'){setNavigationFollow(true);followNavigationPosition(p,false,0,Date.now(),true)}else state.map.panTo(new kakao.maps.LatLng(p.latitude,p.longitude))}return p}
function clearSearchMarkers(){state.searchMarkers.forEach(m=>m.setMap(null));state.searchMarkers=[]}
function clearRouteEndpointMarkers(){state.routeEndpointMarkers.forEach(marker=>marker.setMap(null));state.routeEndpointMarkers=[]}
function selectedRouteEndpoint(){return state.routes[state.selectedRoute]?._points?.at(-1)||state.destination}
function drawRouteEndpointMarkers(navigation=false){clearRouteEndpointMarkers();const add=(point,label,type)=>{if(!point)return;const content=document.createElement('div');content.className=`route-endpoint-marker ${type}`;content.style.width='40px';content.style.height='40px';content.innerHTML=`<span>${label}</span>`;state.routeEndpointMarkers.push(new kakao.maps.CustomOverlay({position:new kakao.maps.LatLng(point.latitude,point.longitude),content,xAnchor:.5,yAnchor:1.15,zIndex:10,map:state.map}))};if(!navigation)add(state.departure,'출발','departure');add(selectedRouteEndpoint(),'도착','destination')}
function clearRoutes(){state.routeLines.forEach(l=>l?.setMap(null));state.routeLines=[];clearRouteEndpointMarkers()}
function showMarkers(places){clearSearchMarkers();const bounds=new kakao.maps.LatLngBounds();places.forEach((p,i)=>{const ll=new kakao.maps.LatLng(p.latitude,p.longitude);const m=new kakao.maps.Marker({position:ll,map:state.map,zIndex:3});kakao.maps.event.addListener(m,'click',()=>openPlace(p));state.searchMarkers.push(m);bounds.extend(ll)});if(places.length){state.searchMapFitPending=true;state.map.setBounds(bounds,60,40,Math.min(360,innerHeight*.42))}}

function renderScreen(screen,push=true,data={}){state.screen=screen;const navMap=screen==='navigation'||screen==='navigation-place'||state.navigationSearch&&(screen==='search'||screen==='results');document.body.classList.toggle('navigation-active',navMap);[ui.mapHeader,ui.quick,ui.search,ui.searchHere,ui.routeEditor,ui.sheet,ui.routeCards,ui.start,ui.bottom,ui.nav].forEach(x=>x.classList.add('hidden'));ui.controls.classList.remove('hidden');if(screen==='map'){ui.mapHeader.classList.remove('hidden');ui.quick.classList.remove('hidden');ui.bottom.classList.remove('hidden');setControlBottom(78)}else if(screen==='search'){ui.search.classList.remove('hidden');ui.controls.classList.add('hidden');setTimeout(()=>$('#searchInput').focus(),30)}else if(screen==='results'||screen==='place'){if(!state.navigationSearch)ui.mapHeader.classList.remove('hidden');ui.sheet.classList.remove('hidden');setSheet('mid')}else if(screen==='navigation-place'){ui.sheet.classList.remove('hidden');ui.controls.classList.add('hidden');syncNavigationViewport()}else if(screen==='route'){ui.routeEditor.classList.remove('hidden');ui.routeCards.classList.remove('hidden');ui.start.classList.remove('hidden');setControlBottom(250)}else if(screen==='navigation'){ui.nav.classList.remove('hidden');ui.controls.classList.add('hidden');syncNavigationViewport()}if(!navMap&&state.currentLocation)setGpsMarker(state.currentLocation,false);if(push)history.pushState({screen,...data},'',`#${screen}`);setTimeout(()=>state.map?.relayout(),50)}
function restoreScreen(screen){renderScreen(screen,false);if(screen!=='route'&&screen!=='navigation'&&screen!=='navigation-place')clearRoutes();if(screen==='map')clearSearchMarkers();else if(screen==='results'){showMarkers(state.searchResults);renderResultsContent(state.searchResults,state.searchQuery)}else if(screen==='place'&&state.selectedPlace){const p=state.selectedPlace;state.map.panTo(new kakao.maps.LatLng(p.latitude,p.longitude));renderPlaceContent(p)}else if(screen==='navigation-place'&&state.selectedPlace)renderNavigationPlaceContent(state.selectedPlace);else if(screen==='route'&&state.routes.length){clearSearchMarkers();drawRoutes();renderRouteCards()}else if(screen==='navigation'&&state.routes[state.selectedRoute]){state.navigationSearch=false;clearSearchMarkers();state.routeLines.forEach((l,i)=>{if(l)l.setMap(i===state.selectedRoute?state.map:null)});state.routeLines[state.selectedRoute]?.setOptions({strokeWeight:8,strokeColor:'#0878f9',strokeOpacity:.95,zIndex:8});drawRouteEndpointMarkers(true);if(state.nav.watchId==null)startWatch();restoreNavigationSearchViewport();setGpsMarker(state.currentLocation,true,state.nav.heading);updateNavHud(state.currentLocation)}}
function handlePopState(e){clearTimeout(searchTimer);cancelSearch();state.routeSeq++;if(state.screen==='navigation'){cancelNavigationReturn();if(state.nav.watchId!=null){navigator.geolocation.clearWatch(state.nav.watchId);state.nav.watchId=null}}const entry=e.state||{},screen=entry.screen||'map';state.navigationSearch=!!entry.navigationSearch;if(screen==='results'&&Array.isArray(entry.places)){state.searchResults=entry.places;state.searchQuery=entry.q||''}else if((screen==='place'||screen==='navigation-place')&&entry.place)state.selectedPlace=entry.place;restoreScreen(screen)}
window.addEventListener('popstate',handlePopState);
function setControlBottom(px){ui.controls.style.setProperty('--control-bottom',`${px}px`)}
function setSheet(mode){ui.sheet.classList.remove('place-detail');const h=ui.sheet.offsetHeight||Math.min(innerHeight*.66,560),y=mode==='low'?h*.68:mode==='high'?h*.08:h*.38;sheetY=y;ui.sheet.style.setProperty('--sheet-y',`${y}px`);setControlBottom(Math.max(90,h-y+18))}
function hideSheet(){ui.sheet.classList.remove('place-detail');ui.sheet.classList.add('hidden');setControlBottom(90)}

function cancelSearch(){state.searchSeq++;state.searchController?.abort();state.searchController=null}
const RECENT_SEARCH_KEY='ridemate_recent_searches';
function readRecentSearches(){try{const items=JSON.parse(localStorage.getItem(RECENT_SEARCH_KEY)||'[]');return Array.isArray(items)?items.filter(item=>item&&typeof item.query==='string').slice(0,10):[]}catch{return[]}}
function saveRecentSearch(item){if(!item?.query?.trim())return;const entry={query:item.query.trim(),...(item.place?{place:item.place}:{})},key=entry.place?`place:${entry.place.id||`${entry.place.latitude},${entry.place.longitude}`}`:`query:${normalize(entry.query)}`,items=readRecentSearches().filter(saved=>(saved.place?`place:${saved.place.id||`${saved.place.latitude},${saved.place.longitude}`}`:`query:${normalize(saved.query)}`)!==key);localStorage.setItem(RECENT_SEARCH_KEY,JSON.stringify([entry,...items].slice(0,10)));renderRecentSearches()}
function renderRecentSearches(){const box=$('#recentSearches');if(!box)return;const items=readRecentSearches();box.innerHTML=items.map((item,i)=>`<button class="recent" data-recent="${i}">${esc(item.place?.name||item.query)}</button>`).join('')||'<p class="recent-empty">최근 검색이 없습니다.</p>';box.querySelectorAll('[data-recent]').forEach(button=>button.onclick=()=>{const item=items[+button.dataset.recent];if(item.place)choosePlace(item.place);else{$('#searchInput').value=item.query;doSearch(item.query,false)}})}
function formatPlaceDistance(distance){if(distance==null||distance==='')return'';distance=Number(distance);if(!Number.isFinite(distance)||distance<0)return'';return distance<1000?`${Math.round(distance)}m`:`${(distance/1000).toFixed(1)}km`}
function currentMapRect(){const bounds=state.map?.getBounds?.(),sw=bounds?.getSouthWest?.(),ne=bounds?.getNorthEast?.();return sw&&ne?[sw.getLng(),sw.getLat(),ne.getLng(),ne.getLat()].join(','):''}
async function searchPlaces(q,signal,rect=''){const p=new URLSearchParams({query:q,size:'15'});if(rect)p.set('rect',rect);else if(state.currentLocation){p.set('x',state.currentLocation.longitude);p.set('y',state.currentLocation.latitude)}const r=await fetch('/api/place-search?'+p,{signal});const d=await r.json();if(!r.ok)throw new Error(d.error||'검색 실패');return rankPlaces(d.results||[],q)}
async function doSearch(q,live=false,rect=''){q=q.trim();if(!q)return;ui.searchHere.classList.add('hidden');cancelSearch();const seq=state.searchSeq,controller=new AbortController();state.searchController=controller;try{const places=await searchPlaces(q,controller.signal,rect);if(seq!==state.searchSeq)return;if(live){renderLive(places);return}saveRecentSearch({query:q});renderResults(places,q)}catch(e){if(e.name!=='AbortError'&&seq===state.searchSeq)toast(e.message)}finally{if(seq===state.searchSeq)state.searchController=null}}
function searchCurrentMap(){const rect=currentMapRect();if(!state.searchQuery||!rect)return;return doSearch(state.searchQuery,false,rect)}
async function choosePlace(p,forceDestination=false){saveRecentSearch({query:p.name,place:p});if(state.navigationSearch)return openNavigationPlace(p);const target=forceDestination?'destination':state.editingEndpoint;if(target==='departure'){state.departure=p;state.editingEndpoint=null;if(state.destination)return loadRoutes();state.editingEndpoint='destination';return openSearch('destination')}if(target==='waypoint'){const index=state.editingWaypointIndex==null?state.waypoints.length:state.editingWaypointIndex;if(index<5)state.waypoints[index]=p;state.editingEndpoint=null;state.editingWaypointIndex=null;updateRouteFields();if(state.departure&&state.destination)return loadRoutes();return}if(target==='destination'){state.destination=p;state.editingEndpoint=null;if(!state.departure)state.departure=state.currentLocation||await locate(false).catch(()=>null);if(!state.departure)return toast('출발 위치가 필요합니다.');return loadRoutes()}openPlace(p)}
function renderLive(places){const box=$('#liveResults');box.classList.remove('hidden');$('#searchLanding').classList.add('hidden');box.innerHTML=places.map((p,i)=>{const distance=formatPlaceDistance(p.distance);return`<div class="live-row"><button class="place-main" data-i="${i}"><b>${esc(p.name)}</b><small>${esc(p.category)}</small><small>${esc(p.address)}${distance?` · ${distance}`:''}</small></button><button class="route-mini" data-route="${i}">길찾기</button></div>`}).join('')||'<p>검색 결과가 없습니다.</p>';box.querySelectorAll('[data-i]').forEach(b=>b.onclick=()=>choosePlace(places[+b.dataset.i]));box.querySelectorAll('[data-route]').forEach(b=>b.onclick=()=>choosePlace(places[+b.dataset.route],true));if(places.length)$('#searchInput').blur()}
function renderResultsContent(places,q){ui.sheet.classList.remove('place-detail');ui.sheetContent.innerHTML=`<div class="result-list"><h3>${esc(q)} <small>${places.length}개</small></h3>${places.map((p,i)=>{const distance=formatPlaceDistance(p.distance);return`<div class="result-item"><button class="result-info" data-i="${i}"><b>${esc(p.name)}</b><small>${esc(p.category)}</small><small>${esc(p.address)}${distance?` · ${distance}`:''}</small></button><button class="route-mini" data-route="${i}">길찾기</button></div>`}).join('')||'<p>검색 결과가 없습니다.</p>'}</div>`;ui.sheetContent.querySelectorAll('[data-i]').forEach(b=>b.onclick=()=>choosePlace(places[+b.dataset.i]));ui.sheetContent.querySelectorAll('[data-route]').forEach(b=>b.onclick=()=>choosePlace(places[+b.dataset.route],true))}
function renderResults(places,q){$('#searchInput').blur();ui.searchHere.classList.add('hidden');state.searchResults=places;state.searchQuery=q;if(state.navigationSearch){renderScreen('results',false);history.replaceState({screen:'results',places,q,navigationSearch:true},'',`#results`)}else renderScreen('results',true,{places,q});showMarkers(places);renderResultsContent(places,q)}
function showCompactSheet(){ui.sheet.classList.add('place-detail');sheetY=0;ui.sheet.style.setProperty('--sheet-y','0px');setTimeout(()=>setControlBottom((ui.sheet.offsetHeight||0)+18),0)}
function renderPlaceContent(p){ui.sheetContent.innerHTML=`<div class="detail"><h2>${esc(p.name)}</h2><p>${esc(p.category)}</p><p>${esc(p.address)}</p>${p.phone?`<p>${esc(p.phone)}</p>`:''}${p.distance!=null?`<p>${(p.distance/1000).toFixed(1)} km</p>`:''}<div class="detail-actions"><button id="setStart" class="outline-btn">출발</button><button id="setEnd" class="primary-btn">도착</button></div></div>`;showCompactSheet();$('#setStart').onclick=()=>setDeparture(p);$('#setEnd').onclick=()=>setDestination(p)}
function renderNavigationPlaceContent(p){ui.sheetContent.innerHTML=`<div class="detail navigation-place-detail"><h2>${esc(p.name)}</h2><p>${esc(p.category)}</p><p>${esc(p.address)}</p><div class="detail-actions"><button id="changeNavDestination" class="primary-btn">목적지 변경</button><button id="cancelNavPlace" class="secondary-btn">취소</button></div></div>`;showCompactSheet();$('#changeNavDestination').onclick=()=>replaceNavigationDestination(p);$('#cancelNavPlace').onclick=()=>{state.navigationSearch=false;history.back()}}
function openNavigationPlace(p){state.selectedPlace=p;renderScreen('navigation-place',false,{place:p});history.replaceState({screen:'navigation-place',place:p,navigationSearch:true},'',`#navigation-place`);renderNavigationPlaceContent(p)}
function openPlace(p){if(state.navigationSearch)return openNavigationPlace(p);saveRecentSearch({query:p.name,place:p});state.selectedPlace=p;renderScreen('place',true,{place:p});const ll=new kakao.maps.LatLng(p.latitude,p.longitude);state.map.panTo(ll);renderPlaceContent(p)}
function setDeparture(p){state.departure=p;state.waypoints=[];state.destination=null;state.editingEndpoint='destination';openSearch('destination');toast('출발지를 설정했습니다. 도착지를 선택하세요.')}
async function setDestination(p){state.destination=p;if(!state.departure)state.departure=state.currentLocation||await locate(false).catch(()=>null);if(!state.departure){toast('출발 위치가 필요합니다.');return}await loadRoutes()}
function openSearch(endpoint=null,navigation=false,waypointIndex=null){cancelSearch();state.editingEndpoint=endpoint;state.editingWaypointIndex=endpoint==='waypoint'?waypointIndex:null;if(navigation&&state.map){cancelNavigationReturn();state.navSearchViewport={follow:state.nav.follow,level:state.map.getLevel(),center:state.map.getCenter()};setNavigationFollow(false)}state.navigationSearch=navigation;renderScreen('search',true,{navigationSearch:navigation});$('#searchInput').value='';$('#liveResults').classList.add('hidden');$('#searchLanding').classList.remove('hidden');renderRecentSearches()}

function extractPoints(route){const out=[];const add=(lat,lng)=>{lat=+lat;lng=+lng;if(Number.isFinite(lat)&&Number.isFinite(lng)&&Math.abs(lat)<=90&&Math.abs(lng)<=180)out.push({latitude:lat,longitude:lng})};const walkCoordinates=o=>{if(!Array.isArray(o))return;if(o.length===2&&o.every(v=>Number.isFinite(+v))){add(o[1],o[0]);return}if(o.length>=4&&o.every(Number.isFinite)){for(let i=0;i+1<o.length;i+=2)add(o[i+1],o[i]);return}o.forEach(walkCoordinates)};const walk=o=>{if(!o)return;if(Array.isArray(o)){if(o.length===2&&o.every(v=>Number.isFinite(+v))){const a=+o[0],b=+o[1];Math.abs(a)>90?add(b,a):add(a,b);return}if(o.length>=4&&o.every(Number.isFinite)){for(let i=0;i+1<o.length;i+=2){const a=+o[i],b=+o[i+1];if(Math.abs(a)>90)add(b,a);else add(a,b)}return}o.forEach(walk);return}if(typeof o!=='object')return;if(Array.isArray(o.vertexes))walk(o.vertexes);if(Array.isArray(o.points))o.points.forEach(p=>Array.isArray(p)?(Math.abs(+p[0])>90?add(p[1],p[0]):add(p[0],p[1])):add(p.y??p.latitude,p.x??p.longitude));if(Array.isArray(o.coordinates))walkCoordinates(o.coordinates);['sections','roads','features','legs','steps','path','geometry'].forEach(k=>{if(o[k])walk(o[k])})};walk(route);return out.filter((p,i,a)=>!i||p.latitude!==a[i-1].latitude||p.longitude!==a[i-1].longitude)}
function buildRouteParams(origin,waypoints,destination){const p=new URLSearchParams({start_x:origin.longitude,start_y:origin.latitude,end_x:destination.longitude,end_y:destination.latitude}),via=(waypoints||[]).slice(0,5);if(via.length){p.set('via_x',via.map(point=>point.longitude).join(','));p.set('via_y',via.map(point=>point.latitude).join(','));p.set('v_name',via.map(point=>point.name||'경유').join(','))}return p}
function routeNow(){return globalThis.performance?.now?.()??Date.now()}
function beginRoutePerformance(type,origin,destination){return{type,origin:origin?.name||`${origin?.latitude},${origin?.longitude}`,destination:destination?.name||`${destination?.latitude},${destination?.longitude}`,routeSearchStart:routeNow(),apiRequestStart:null,browserResponseReceived:null,processingComplete:null,mapRenderingComplete:null,server:null}}
function reportRoutePerformance(record){const duration=(end,start)=>Number.isFinite(end)&&Number.isFinite(start)?Math.max(0,end-start):null,format=value=>Number.isFinite(value)?`${value.toFixed(1)} ms`:'n/a',modes=record.server?.modes||{},apiTotal=duration(record.browserResponseReceived,record.apiRequestStart),frontend=duration(record.processingComplete,record.browserResponseReceived),rendering=duration(record.mapRenderingComplete,record.processingComplete),total=duration(record.mapRenderingComplete,record.routeSearchStart);console.groupCollapsed?.('[Route Performance]');['BIKE_ONLY','SHORTEST','ACCESSIBLE'].forEach(mode=>console.log(`${mode} Kakao: ${format(modes[mode]?.durationMs)}`));console.log(`API total: ${format(apiTotal)}`);console.log(`Frontend processing: ${format(frontend)}`);console.log(`Map rendering: ${format(rendering)}`);console.log(`TOTAL: ${format(total)}`);console.table?.([{milestone:'1. Route search start',browserMs:0},{milestone:'2. Frontend API request',browserMs:duration(record.apiRequestStart,record.routeSearchStart)},{milestone:'3. Server request received',serverMs:record.server?.receivedAt},{milestone:'4-5. Kakao requests',serverMs:Object.fromEntries(Object.entries(modes).map(([mode,timing])=>[mode,`${format(timing.startMs)} → ${format(timing.endMs)}`]))},{milestone:'6. Server response ready',serverMs:record.server?.responseReadyMs},{milestone:'7. Browser response received',browserMs:duration(record.browserResponseReceived,record.routeSearchStart)},{milestone:'8. Route processing complete',browserMs:duration(record.processingComplete,record.routeSearchStart)},{milestone:'9. Map/UI rendering complete',browserMs:duration(record.mapRenderingComplete,record.routeSearchStart)}]);console.groupEnd?.();const history=window.__rideMateRoutePerformance||(window.__rideMateRoutePerformance=[]);history.push(record);if(history.length>20)history.splice(0,history.length-20)}
function finishRoutePerformance(record){if(!record||record.mapRenderingComplete!=null)return;const complete=()=>{record.mapRenderingComplete=routeNow();reportRoutePerformance(record)};if(typeof requestAnimationFrame==='function')requestAnimationFrame(()=>requestAnimationFrame(complete));else setTimeout(complete,0)}
async function fetchRoutes(a=state.departure,b=state.destination,waypoints=state.waypoints,performanceRecord=null){const p=buildRouteParams(a,waypoints,b);if(performanceRecord)performanceRecord.apiRequestStart=routeNow();const r=await fetch('/api/bicycle-route?'+p),d=await r.json();if(performanceRecord){performanceRecord.browserResponseReceived=routeNow();performanceRecord.server=d.performance||null}if(!r.ok)throw new Error(d.error||'자전거 경로를 찾을 수 없음');return d.routes||[]}
function prepareRoutes(routes){return routes.filter(r=>{r._points=extractPoints(r.route);r._steps=extractNavigationSteps(r.route);return r._points.length>1&&r.totalDistance>0})}
async function loadRoutes(){if(state.nav.watchId!=null){navigator.geolocation.clearWatch(state.nav.watchId);state.nav.watchId=null}const performanceRecord=typeof beginRoutePerformance==='function'?beginRoutePerformance('initial',state.departure,state.destination):null;state.routeSeq++;const routeSeq=state.routeSeq;clearRoutes();state.routes=[];state.selectedRoute=null;ui.start.classList.add('hidden');renderScreen('route');updateRouteFields();ui.routeCards.innerHTML='<div class="route-card">경로를 찾는 중...</div>';clearSearchMarkers();try{const fetched=await fetchRoutes(state.departure,state.destination,state.waypoints,performanceRecord);if(routeSeq!==state.routeSeq)return;state.routes=prepareRoutes(fetched);if(performanceRecord)performanceRecord.processingComplete=routeNow();if(!state.routes.length)throw new Error('표시 가능한 자전거 경로가 없습니다.');state.selectedRoute=0;drawRoutes();renderRouteCards();ui.start.classList.remove('hidden');if(typeof finishRoutePerformance==='function')finishRoutePerformance(performanceRecord)}catch(e){if(routeSeq!==state.routeSeq)return;if(performanceRecord&&!Number.isFinite(performanceRecord.processingComplete))performanceRecord.processingComplete=routeNow();clearRoutes();state.routes=[];state.selectedRoute=null;ui.start.classList.add('hidden');ui.routeCards.innerHTML=`<div class="route-card">${esc(e.message)}</div>`;toast(e.message);if(typeof finishRoutePerformance==='function')finishRoutePerformance(performanceRecord)}}
function updateRouteFields(){$('#departureField b').textContent=state.departure?.name||'현재 위치';$('#destinationField b').textContent=state.destination?.name||'목적지';const box=$('#waypointFields');box.innerHTML=state.waypoints.map((point,index)=>`<button data-waypoint="${index}"><small>경유 ${index+1}</small><b>${esc(point.name||'경유지')}</b></button>`).join('');box.querySelectorAll('[data-waypoint]').forEach(button=>button.onclick=()=>openSearch('waypoint',false,+button.dataset.waypoint));$('#addWaypointBtn').classList.toggle('hidden',state.waypoints.length>=5)}
function routeFitPadding(viewportHeight,viewportOffsetTop,editorBottom,controlsTop){return{top:Math.max(24,Math.round(editorBottom-viewportOffsetTop)+12),right:24,bottom:Math.max(24,Math.round(viewportOffsetTop+viewportHeight-controlsTop)+12),left:24}}
function fitSelectedRoute(){const route=state.routes[state.selectedRoute],points=route?._points;if(!state.map||!points?.length)return;const bounds=new kakao.maps.LatLngBounds();points.forEach(point=>bounds.extend(new kakao.maps.LatLng(point.latitude,point.longitude)));[state.departure,state.destination].forEach(point=>{if(point)bounds.extend(new kakao.maps.LatLng(point.latitude,point.longitude))});const viewport=window.visualViewport,height=viewport?.height||window.innerHeight||innerHeight,offsetTop=viewport?.offsetTop||0,editorBottom=$('#routeEditor').getBoundingClientRect().bottom,controlsTop=Math.min($('#routeCards').getBoundingClientRect().top,$('#startNavBtn').getBoundingClientRect().top),padding=routeFitPadding(height,offsetTop,editorBottom,controlsTop);if(!bounds.isEmpty())state.map.setBounds(bounds,padding.top,padding.right,padding.bottom,padding.left)}
function drawRoutes(){clearRoutes();state.routes.forEach((r,i)=>{const pts=r._points||extractPoints(r.route);r._points=pts;const path=pts.map(p=>new kakao.maps.LatLng(p.latitude,p.longitude));if(path.length>1){const line=new kakao.maps.Polyline({map:state.map,path,strokeWeight:i===state.selectedRoute?8:5,strokeColor:i===state.selectedRoute?'#0878f9':'#98a7b8',strokeOpacity:i===state.selectedRoute?.95:.62,strokeStyle:'solid',zIndex:i===state.selectedRoute?8:3});state.routeLines.push(line)}else state.routeLines.push(null)});drawRouteEndpointMarkers(false);fitSelectedRoute()}
function selectRoute(i){state.selectedRoute=i;state.routeLines.forEach((l,j)=>{if(!l)return;l.setOptions({strokeWeight:j===i?8:5,strokeColor:j===i?'#0878f9':'#98a7b8',strokeOpacity:j===i?.95:.62,zIndex:j===i?8:3})});drawRouteEndpointMarkers(false);fitSelectedRoute();renderRouteCards()}
function renderRouteCards(){ui.routeCards.innerHTML=state.routes.map((r,i)=>`<button class="route-card ${i===state.selectedRoute?'active':''}" data-i="${i}"><b>${esc(r.label||`경로 ${i+1}`)}</b><strong>${fmtMin(r.totalTime)}</strong><small>${fmtKm(r.totalDistance)}</small></button>`).join('');ui.routeCards.querySelectorAll('[data-i]').forEach(b=>b.onclick=()=>selectRoute(+b.dataset.i))}

function bearing(a,b){const p=Math.PI/180,y=Math.sin((b.longitude-a.longitude)*p)*Math.cos(b.latitude*p),x=Math.cos(a.latitude*p)*Math.sin(b.latitude*p)-Math.sin(a.latitude*p)*Math.cos(b.latitude*p)*Math.cos((b.longitude-a.longitude)*p);return(Math.atan2(y,x)*180/Math.PI+360)%360}
